data.minimal_example:
NumPad(
  arabicDigits: true,
  onType: (value) {
    number += value;
    setState(() {});
  },
  rightWidget: IconButton(
    icon: const Icon(Icons.backspace),
    onPressed: () {
      if (number.isNotEmpty) {
        number = number.substring(0, number.length - 1);
        setState(() {});
      }
    },
  ),
);
